# 使用并查集找到连通分量
class UnionFind:
    def __init__(self, items):
        self.parent = {item: item for item in items}
        self.size = {item: 1 for item in items}

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return
        if self.size[px] < self.size[py]:
            px, py = py, px
        self.parent[py] = px
        self.size[px] += self.size[py]

    def groups(self):
        groups = {}
        for item in self.parent:
            g = self.find(item)
            if g not in groups:
                groups[g] = []
            groups[g].append(item)
        return list(groups.values())

# 邻接关系（45度对角线连接）
adj = set()
for i in range(len(positions)):
    for j in range(i+1, len(positions)):
        r1, c1 = positions[i]
        r2, c2 = positions[j]
        if abs(r2 - r1) == abs(c2 - c1):
            # 按位置排序用于存储到集合
            if (c1, r1) <= (c2, r2):
                adj.add(((c1, r1), (c2, r2)))
            else:
                adj.add(((c2, r2), (c1, r1)))

uf = UnionFind(positions)
for (a, b) in adj:
    r1, c1 = a
    r2, c2 = b
    uf.union(a, b)

groups = uf.groups()
for i, g in enumerate(groups):
    g_sorted = sorted(g)
    print(f"组 {i}: {g_sorted}")

