        r1, c1 = positions[i]
        r2, c2 = positions[j]
        if abs(r2 - r1) == abs(c2 - c1):
            adj_list[positions[i]].append(positions[j])
            adj_list[positions[j]].append(positions[i])

uf = UnionFind(positions)
for p in adj_list:
